head.script:
scwin.getType = function(info) {
    var rowIndex = info.rowIndex;
    var colIndex = info.colIndex;
    var returnInfo;
    var inputType = inputTypeList.getCellData(rowIndex, colIndex);
    switch (inputType) {
        case "radio":
            returnInfo = {
                id: "dynamic_radio_" + rowIndex + "_" + colIndex,
                inputType: "radio",
                options: {
                    groupName: "radio_" + rowIndex
                }
            }
            break;
        case "checkbox":
            returnInfo = {
                id: "dynamic_checkbox_" + rowIndex + "_" + colIndex,
                inputType: "checkbox",
                options: {}
            }
            break;
        case "button":
            returnInfo = {
                id: "dynamic_button_" + rowIndex + "_" + colIndex,
                inputType: "button",
                options: {}
            }
            break;
        case "calendar":
            returnInfo = {
                id: "dynamic_calendar_" + rowIndex + "_" + colIndex,
                inputType: "calendar",
                options: {
                    viewType: "icon"
                }
            }
            break;
        case "image":
            returnInfo = {
                id: "dynamic_image_" + rowIndex + "_" + colIndex,
                inputType: "image",
                options: {
                    imageSrc: "/SAMPLE/W5/project/dynamic/img.gif"
                }
            }
            break;
        case "link":
            returnInfo = {
                id: "dynamic_link_" + rowIndex + "_" + colIndex,
                inputType: "link",
                options: {}
            }
            break;
        case "select":
            returnInfo = {
                id: "dynamic_select_" + rowIndex + "_" + colIndex,
                inputType: "select",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList3",
                    label: "label",
                    value: "value"
                }
            }
            break;
        case "autoComplete":
            returnInfo = {
                id: "dynamic_autoComplete_" + rowIndex + "_" + colIndex,
                inputType: "autoComplete",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList3",
                    label: "label",
                    value: "value"
                }
            }
            break;
        case "checkcombobox":
            returnInfo = {
                id: "dynamic_checkcombobox_" + rowIndex + "_" + colIndex,
                inputType: "checkcombobox",
                options: {
                    viewType: "icon"
                },
                itemSet: {
                    nodeset: "data:dataList3",
                    label: "label",
                    value: "value"
                }
            }
            break;
        case "textarea":
            returnInfo = {
                id: "dynamic_textarea_" + rowIndex + "_" + colIndex,
                inputType: "textarea",
                options: {}
            }
            break;
        case "text":
            returnInfo = {
                id: "dynamic_text_" + rowIndex + "_" + colIndex,
                inputType: "text",
                options: {}
            }
            break;
        case "textImage":
            returnInfo = {
                id: "dynamic_textImage_" + rowIndex + "_" + colIndex,
                inputType: "textImage",
                options: {
                    viewType: "icon",
                    imageSrc: "/SAMPLE/W5/project/dynamic/alz.jpg",
                    textAlign: "center"
                }
            }
            break;
    }
    if (returnInfo) {
        ngmf.trace("[typeGetter] (" + rowIndex + ", " + colIndex + ") : " + returnInfo.inputType);
    }
    return returnInfo;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}

scwin.b1_onclick = function(e) {
    var rowIndex = WebSquare.util.getNumber(rowTb.getValue());
    var inputType = s1.getValue();
    for (var i = 0; i < inputTypeList.getColCnt(); i++) {
        inputTypeList.setCellData(rowIndex, i, inputType);
    }
    gridView1.refreshRow(rowIndex);
};
scwin.b2_onclick = function(e) {
    var colIndex = WebSquare.util.getNumber(colTb.getValue());
    var inputType = s2.getValue();
    for (var i = 0; i < inputTypeList.getRowCount(); i++) {
        inputTypeList.setCellData(i, colIndex, inputType);
    }
    gridView1.refreshColumn(colIndex);
};
scwin.b3_onclick = function(e) {
    var colIndex = WebSquare.util.getNumber(cellColTb.getValue());
    var rowIndex = WebSquare.util.getNumber(cellRowTb.getValue());
    var inputType = s3.getValue();
    inputTypeList.setCellData(rowIndex, colIndex, inputType);
    gridView1.refreshCell(rowIndex, colIndex);
};
scwin.inputTypeList_oncelldatachange = function(info) {
    //debugger;
};
scwin.onpageload = function() {
    if (typeof scwin.onpageload === "function") {
        //scwin.onpageload();
    }
    if (!scwin.promise) {
        scwin.promise = {};
    }
    window.dataArr = [
        "radio", "radio",
        "checkbox", "checkbox",
        "button", "button",
        "calendar", "calendar",
        "image", "image",
        "link", "link",
        "select", "select",
        "autoComplete", "autoComplete",
        "checkcombobox", "checkcombobox",
        "textarea", "textarea",
        "text", "text",
        "textImage", "textImage"
    ];
    dataList2.setData(dataArr);
    dataList3.setData(dataArr);
    window._dataArr = [];
    for (var i = 0; i < 300; i++) {
        _dataArr.push("");
    }
    dataList1.setData(_dataArr.slice(0));
    inputTypeList.setData(_dataArr.slice(0));
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
